                        const bool revK = (double)K.dxF < 0.0 || s.rev != 0;
                        const double headTol =
                            (slopeUnderside(c.flip != 0, sp->slopeDir)
                             && slopeNudgeMode(c.mode) && input
                             && slopeBVar22(c.flip != 0, sp->slopeDir) == revK && !isSlopeK)
                                ? (wasSlopeK ? 2.0 : 1.0)
                                : 0.0;
